import { useState, type FormEvent } from 'react';
import { Eye, EyeOff, KeyRound } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { toast } from 'sonner';
import { getLocalAdminPassword, PASSWORD_KEY } from '@/pages/AdminLoginPage/AdminLoginPage';
import { useSyncService } from '@/context/SyncServiceContext';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';

export default function AdminChangePasswordPage() {
  const { adminT } = useI18n();
  const { markDirty } = useSyncService();
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showCurrent, setShowCurrent] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [errors, setErrors] = useState<{ current?: string; new?: string; confirm?: string }>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const resetForm = () => {
    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
    setErrors({});
  };

  const validate = (): boolean => {
    const next: typeof errors = {};
    const current = getLocalAdminPassword();

    if (!currentPassword) {
      next.current = adminT('admin.changePassword.currentRequired');
    } else if (currentPassword !== current) {
      next.current = adminT('admin.changePassword.currentIncorrect');
    }

    if (!newPassword) {
      next.new = adminT('admin.changePassword.newRequired');
    } else if (newPassword.length < 6) {
      next.new = adminT('admin.changePassword.newTooShort');
    } else if (newPassword === currentPassword) {
      next.new = adminT('admin.changePassword.newSameAsCurrent');
    }

    if (!confirmPassword) {
      next.confirm = adminT('admin.changePassword.confirmRequired');
    } else if (confirmPassword !== newPassword) {
      next.confirm = adminT('admin.changePassword.confirmMismatch');
    }

    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    if (!validate()) return;

    setIsSubmitting(true);
    try {
      localStorage.setItem(PASSWORD_KEY, newPassword);
      // 标记 settings 模块为脏，下次 Sync to GitHub 时会一并同步到 data/settings.json
      try { markDirty('settings'); } catch { /* ignore */ }
      toast.success(adminT('admin.changePassword.successMsg'));
      resetForm();
    } catch {
      toast.error(adminT('admin.changePassword.errorMsg'));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.changePassword.title') }]}
      />
      <div>
        <h1 className="text-2xl font-bold text-foreground">{adminT('admin.changePassword.title')}</h1>
        <p className="text-sm text-muted-foreground mt-1">
          {adminT('admin.changePassword.subtitle')}
        </p>
      </div>

      <Card className="border-border/40 bg-card max-w-lg">
        <CardHeader className="pb-4">
          <div className="flex items-center gap-3">
            <div className="size-10 rounded-md bg-primary/10 flex items-center justify-center">
              <KeyRound className="size-5 text-primary" />
            </div>
            <div>
              <CardTitle className="text-base">{adminT('admin.changePassword.cardTitle')}</CardTitle>
              <CardDescription>
                {adminT('admin.changePassword.cardDesc')}
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* 当前密码 */}
            <div>
              <label className="text-xs font-medium text-foreground mb-1.5 block">
                {adminT('admin.changePassword.currentPassword')} <span className="text-destructive">*</span>
              </label>
              <div className="relative">
                <KeyRound className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  type={showCurrent ? 'text' : 'password'}
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  placeholder={adminT('admin.changePassword.currentPasswordPh')}
                  className="pl-9 pr-9 bg-background/60"
                  autoComplete="current-password"
                />
                <button
                  type="button"
                  onClick={() => setShowCurrent((v) => !v)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-muted-foreground hover:text-foreground"
                  aria-label={showCurrent ? adminT('admin.changePassword.hidePassword') : adminT('admin.changePassword.showPassword')}
                >
                  {showCurrent ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                </button>
              </div>
              {errors.current && (
                <p className="text-xs text-destructive mt-1.5">{errors.current}</p>
              )}
            </div>

            {/* 新密码 */}
            <div>
              <label className="text-xs font-medium text-foreground mb-1.5 block">
                {adminT('admin.changePassword.newPassword')} <span className="text-destructive">*</span>
                <span className="text-muted-foreground font-normal ml-1">{adminT('admin.changePassword.minLengthHint')}</span>
              </label>
              <div className="relative">
                <KeyRound className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  type={showNew ? 'text' : 'password'}
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  placeholder={adminT('admin.changePassword.newPasswordPh')}
                  className="pl-9 pr-9 bg-background/60"
                  autoComplete="new-password"
                />
                <button
                  type="button"
                  onClick={() => setShowNew((v) => !v)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-muted-foreground hover:text-foreground"
                  aria-label={showNew ? adminT('admin.changePassword.hidePassword') : adminT('admin.changePassword.showPassword')}
                >
                  {showNew ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                </button>
              </div>
              {errors.new && (
                <p className="text-xs text-destructive mt-1.5">{errors.new}</p>
              )}
            </div>

            {/* 确认新密码 */}
            <div>
              <label className="text-xs font-medium text-foreground mb-1.5 block">
                {adminT('admin.changePassword.confirmPassword')} <span className="text-destructive">*</span>
              </label>
              <div className="relative">
                <KeyRound className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  type={showConfirm ? 'text' : 'password'}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder={adminT('admin.changePassword.confirmPasswordPh')}
                  className="pl-9 pr-9 bg-background/60"
                  autoComplete="new-password"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirm((v) => !v)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-muted-foreground hover:text-foreground"
                  aria-label={showConfirm ? adminT('admin.changePassword.hidePassword') : adminT('admin.changePassword.showPassword')}
                >
                  {showConfirm ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                </button>
              </div>
              {errors.confirm && (
                <p className="text-xs text-destructive mt-1.5">{errors.confirm}</p>
              )}
            </div>

            <div className="flex items-center gap-2 pt-2">
              <Button
                type="submit"
                className="bg-primary hover:bg-primary/90 text-primary-foreground"
                disabled={isSubmitting}
              >
                {isSubmitting ? adminT('admin.changePassword.submitting') : adminT('admin.changePassword.submit')}
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={resetForm}
                disabled={isSubmitting}
              >
                {adminT('admin.changePassword.reset')}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
